<section class="mt-7"><h2 class="text-xl font-extrabold"><?= esc($title) ?></h2><p class="text-sm text-[#78908c]"><?= esc($subtitle) ?></p><div class="mt-6 grid gap-5 md:grid-cols-2 xl:grid-cols-3"><?php foreach($items as $item): ?><article class="card p-6"><div class="flex items-start justify-between"><span class="grid h-11 w-11 place-items-center rounded-xl bg-[#daf2eb] text-mint"><i data-lucide="<?= $active==='templates'?'layout-template':($active==='team'?'user-round':($active==='forms'?'panel-top':'workflow')) ?>" class="h-5"></i></span><?php if(isset($item['status'])): ?><span class="rounded-full bg-[#dff4e9] px-2 py-1 text-xs font-bold text-[#28775f]"><?= esc(ucfirst($item['status'])) ?></span><?php endif ?></div><h3 class="mt-5 font-extrabold"><?= esc($item['name']) ?></h3><p class="mt-1 text-sm text-[#78908c]"><?= esc($item['category'] ?? $item['email'] ?? ucfirst(str_replace('_',' ',$item['form_type'] ?? $item['trigger_type']??''))) ?></p><?php if(isset($item['role'])): ?><p class="mt-4 text-xs font-bold uppercase tracking-wider text-sea"><?= esc($item['role']) ?></p><?php endif ?><?php if(isset($item['submissions'])): ?><p class="mt-4 text-sm font-bold"><?= number_format($item['submissions']) ?> submissions</p><?php endif ?></article><?php endforeach ?></div></section>
